// routing.dlx-sources: Every queue that can dead-letter into a queue (amendment A-2)
// Generated by `pnpm nx g @app/generators:action routing.dlx-sources`, then edited. Run
// `pnpm nx run contracts:api-docs` so the committed API documents follow.
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineAction } from '../kit/define-action.ts';
import {
  DlxSourceSchema,
  DlxTruncationSchema,
  HELD_DEATH_SOURCES_MAX,
  ROUTING_LIST_MAX,
  UnknownReasonSchema,
} from './routing-types.ts';
import {
  SnapshotMetaSchema,
  TOPOLOGY_NAME_MAX,
  TopologyGapsSchema,
  TopologyNameSchema,
  VhostNameSchema,
} from './topology-types.ts';

export const RoutingDlxSourcesInputSchema = z.strictObject({
  cid: ConnectionIdSchema,
  vhost: VhostNameSchema,
  /** The queue the dead letters would arrive in. */
  queue: TopologyNameSchema,
  /**
   * The source queues named by the broker's `x-death` of the messages the queue holds, as the
   * caller read them (the peek preflight). A queue that is not a known source is listed as a
   * possible source with an unknown limit, even when no current queue feeds this one.
   */
  heldDeathSources: z
    .array(z.string().max(TOPOLOGY_NAME_MAX))
    .max(HELD_DEATH_SOURCES_MAX)
    .optional(),
  /** Read the broker again instead of using a snapshot taken in the last seconds. */
  refresh: z.boolean().optional(),
});

export const RoutingDlxSourcesOutputSchema = z.strictObject({
  vhost: VhostNameSchema,
  queue: TopologyNameSchema,
  /** Sorted by queue name; the first ROUTING_LIST_MAX (`sourcesMore` counts the rest). */
  sources: z.array(DlxSourceSchema).max(ROUTING_LIST_MAX),
  sourcesMore: z.number().int().nonnegative(),
  /**
   * An empty `sources` means "no hazard" only when `complete` is true. When `complete` is false the
   * list may be missing sources, and `unknownReasons` says why; a consumer treats the limit of the
   * queue's sources as finite and unknown.
   */
  complete: z.boolean(),
  unknownReasons: z.array(UnknownReasonSchema).max(ROUTING_LIST_MAX),
  /** Reasons that are not listed. */
  unknownReasonsMore: z.number().int().nonnegative(),
  truncation: DlxTruncationSchema,
  /** The `x-death` sources the caller passed, so a consumer can tell "looked at" from "not looked at". */
  heldDeathSourcesConsidered: z
    .array(z.string().max(TOPOLOGY_NAME_MAX))
    .max(HELD_DEATH_SOURCES_MAX),
  gaps: TopologyGapsSchema,
  snapshot: SnapshotMetaSchema,
});

export const routingDlxSources = defineAction({
  id: 'routing.dlx-sources',
  kind: 'query',
  summary:
    'Every queue that can dead-letter into a queue, with the limit of each and whether the list is complete',
  input: RoutingDlxSourcesInputSchema,
  output: RoutingDlxSourcesOutputSchema,
  permission: 'broker.read',
  risk: 'none',
  planning: 'none',
  audit: 'none',
  target: (input) => ({
    connectionId: input.cid,
    vhost: input.vhost,
    kind: 'queue',
    name: input.queue,
  }),
  http: { method: 'POST', path: '/connections/{cid}/routing/dlx-sources' },
  mcp: {
    expose: true,
    mutating: false,
    title: 'Dead-letter sources of a queue',
    description:
      'Every queue whose dead letters can arrive in this queue, with its delivery limit, and whether the list is complete. An empty list is "no hazard" only when complete is true.',
  },
  cli: { command: 'routing dlx-sources' },
  since: '1.0',
});
